    "കമ്മീഷൻ, GST, ഫീസ് എന്നിവ ചേർന്ന് ലിസ്റ്റ് വിലയുടെ 100% അല്ലെങ്കിൽ അതിലധികമാകുന്നു, അതിനാൽ ഒരു മെനു വിലയ്ക്കും ഈ ഇനത്തിൽ നിങ്ങളുടെ ലക്ഷ്യ ടേക്ക്-ഹോം തിരികെ നൽകാനാവില്ല. കമ്മീഷനോ ഫീസോ കുറച്ച് ശ്രമിക്കുക, അല്ലെങ്കിൽ ഈ മാർജിനിൽ ഇത് ഓൺലൈനിൽ ലിസ്റ്റ് ചെയ്യുന്നത് പുനഃപരിശോധിക്കുക.",
  ompAssumption:
    "കമ്മീഷനും ഗേറ്റ്‌വേ ഫീസും ലിസ്റ്റ് വിലയിൽ ഈടാക്കുന്നു എന്നും, ലിസ്റ്റ് വിലയിൽ നിങ്ങൾ ഇനത്തിന് ഈടാക്കുന്ന GST ഇതിനകം ഉൾപ്പെട്ടിട്ടുണ്ട് എന്നും അനുമാനിക്കുന്നു. അഗ്രിഗേറ്റർ കരാറുകൾ വ്യത്യാസപ്പെടുന്നു — പുതിയ വിലകൾ നടപ്പാക്കുന്നതിന് മുമ്പ് യഥാർത്ഥ പേഔട്ട് റിപ്പോർട്ടുമായി പരിശോധിക്കുക.",
