  mdrCapApplied: "MDR ഈ രീതിയുടെ പരമാവധി പരിധിയിൽ എത്തി, അതിനാൽ പേയ്‌മെന്റ് എത്ര വലുതായാലും അത് അതേപടി നിൽക്കും.",
