  mdrAssumption: "MDR ഇടപാട് മൂല്യത്തിന്റെ ശതമാനമായും കൂടെ ഏതെങ്കിലും സ്ഥിര ഫീസായും ചുമത്തുന്നു, ജിഎസ്ടി വിൽപ്പനയ്ക്കല്ല MDR-നുതന്നെ വരുന്നു എന്ന് കരുതുന്നു. അവസാന വാക്ക് നിങ്ങളുടെ അക്വയറർ കരാറിന്റേതാണ് — ഈ സംഖ്യകൾ വെച്ച് വില നിശ്ചയിക്കുന്നതിന് മുൻപ് ഒരു യഥാർഥ സെറ്റിൽമെന്റ് റിപ്പോർട്ട് നോക്കുക.",
