  mdrAssumption: "ਇਹ ਮੰਨ ਕੇ ਚੱਲਦਾ ਹੈ ਕਿ MDR ਲੈਣ-ਦੇਣ ਮੁੱਲ ਦੇ ਫ਼ੀਸਦ ਵਜੋਂ ਅਤੇ ਨਾਲ ਕੋਈ ਮਿੱਥੀ ਫ਼ੀਸ ਵਜੋਂ ਲਿਆ ਜਾਂਦਾ ਹੈ, ਤੇ ਜੀਐੱਸਟੀ ਵਿਕਰੀ ਉੱਤੇ ਨਹੀਂ ਸਗੋਂ MDR ਉੱਤੇ ਹੀ ਬੈਠਦਾ ਹੈ। ਆਖ਼ਰੀ ਗੱਲ ਤੁਹਾਡੇ ਐਕਵਾਇਰਰ ਬੈਂਕ ਦੇ ਸਮਝੌਤੇ ਦੀ ਹੈ — ਇਨ੍ਹਾਂ ਅੰਕੜਿਆਂ ਉੱਤੇ ਭਾਅ ਤੈਅ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਕੋਈ ਅਸਲੀ ਸੈਟਲਮੈਂਟ ਰਿਪੋਰਟ ਵੇਖ ਲਵੋ।",
